data.test_script:
import { render } from '@testing-library/react';
import UserCode from './UserCode';

test('Must display Age and Age Next Year computed correctly', () => {
  const { container } = render(<UserCode />);
  const text = container.textContent;

  const ageMatch = text.match(/Age:\s*(\d+)/i);
  const ageNextMatch = text.match(/Age Next Year:\s*(\d+)/i);

  expect(ageMatch).toBeTruthy();
  expect(ageNextMatch).toBeTruthy();

  const age = parseInt(ageMatch[1], 10);
  const ageNext = parseInt(ageNextMatch[1], 10);

  expect(ageNext).toBe(age + 1);
});

